import{_t as e,it as t,n,rt as r}from"./chunks/framework.uM88Qy9F.js";var i=JSON.parse(`{"title":"布局与主题","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/theme.md","filePath":"frontend/theme.md","lastUpdated":1794176980000}`),a={name:`frontend/theme.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="布局与主题" tabindex="-1">布局与主题 <a class="header-anchor" href="#布局与主题" aria-label="Permalink to “布局与主题”">​</a></h1><p>本页说明前端的设计令牌、样式约束、布局与偏好同步，适用于前端开发者。</p><p>XiHan.UI 是组件与样式契约的真源：组件只认 <code>--xh-*</code> 语义令牌，应用把自己的配色、圆角与布局语义映射上去。</p><h2 id="令牌分层" tabindex="-1">令牌分层 <a class="header-anchor" href="#令牌分层" aria-label="Permalink to “令牌分层”">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>位置</th><th>作用</th></tr></thead><tbody><tr><td>应用令牌</td><td><code>packages/design/variables.css</code></td><td>HSL 分量形式的应用令牌（<code>--primary</code>、<code>--background</code>、<code>--radius</code>…），明暗两套</td></tr><tr><td>令牌桥</td><td><code>packages/design/xihan-ui.css</code></td><td>在 <code>xihan.overrides</code> 层把 XiHan.UI 的 <code>--xh-*</code> 改写到应用令牌上；<code>:root</code>、<code>.dark</code> 与浮层壳的 <code>[data-theme]</code> 各写一份，组件库与浮层随之换色</td></tr><tr><td>Tailwind</td><td><code>src/styles/index.css</code></td><td>样式总入口：定死层序，<code>@theme inline</code> 把页面用到的主题色与排版工具类映射到 <code>hsl(var(--x))</code> 与 <code>--xh-*</code>，在使用处解析，嵌套的 <code>.dark</code> 容器随之切换</td></tr><tr><td>应用样式</td><td><code>packages/design/*.css</code>、<code>src/styles/admin-page.css</code></td><td>宿主基线、动效令牌桥、页面过渡、原生滚动条与共享结构件，只读 <code>--xh-*</code> 语义令牌</td></tr></tbody></table><p>偏好由 <code>useTheme</code> 与 <code>useHtmlStyle</code> 写到 <code>&lt;html&gt;</code>：明暗写 <code>.dark</code> / <code>.light</code> 类与 <code>data-theme</code>，密度写 <code>data-density</code>，图表配色写 <code>data-xh-chart-palette</code>，主题色写 <code>--primary</code> 与派生的品牌色阶，圆角写 <code>--radius</code> / <code>--radius-card</code>，另有根字号、灰度与色弱滤镜。</p><h2 id="约束" tabindex="-1">约束 <a class="header-anchor" href="#约束" aria-label="Permalink to “约束”">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>规则</th></tr></thead><tbody><tr><td>圆角</td><td>偏好设置的 <code>--radius</code> 接到组件库的圆角种子 <code>--xh-radius-seed</code>：控件、承载面与浮层同一档（卡片取 <code>--radius-card</code>），内嵌件（菜单与下拉的行、方框、已选标签）取一半，对话框与抽屉朝页面的两角、通知卡片取 1.25 倍；自写样式只写形状角色 <code>--xh-shape-control / surface / overlay / inset / sheet</code>，不写 <code>--xh-radius-*</code> 档位；<code>pill</code> 只用于明确的胶囊语义，正方盒取 <code>circle</code></td></tr><tr><td>按压</td><td>按钮按下只换面、不缩放（随组件库缺省，不改写 <code>--xh-motion-scale-press</code>）；减弱动效下去掉非必要的位移</td></tr><tr><td>聚焦环</td><td>与组件库同一道：<code>outline: var(--xh-ring-width) solid var(--xh-ring-focus); outline-offset: var(--xh-ring-offset)</code>，2px 画在元素自己的盒内，外沿与边框外沿重合，裁切容器不必为它留位。面是实心或任意颜色时内侧衬一道底色间隔线：<code>box-shadow: inset 0 0 0 calc(var(--xh-ring-width) + var(--xh-ring-gap-width)) var(--xh-ring-gap)</code>（有边框时扣掉边框宽）</td></tr><tr><td>浮层</td><td>锚定浮层走 frosted（实体底 + 描边 + 柔和投影，不叠背景模糊）；玻璃拟态只用在命令面板、登录与注册页的卡片和右上角工具条、灵动岛、标签总览遮罩、控制中心面板、页面切换的加载遮罩，统一取 <code>packages/design/ui.css</code> 的 <code>.app-glass</code> / <code>--app-glass-*</code></td></tr><tr><td>取值</td><td>颜色、间距、圆角、阴影、层级、动效只用语义令牌，不写裸色值</td></tr><tr><td>CSS 写法</td><td><code>.css</code> 文件和 <code>.vue</code> 的 <code>&lt;style&gt;</code> 块用与 XiHan.UI 皮肤同一套 stylelint 规则（<code>stylelint.config.mjs</code>，随 <code>pnpm lint</code>）：逻辑属性；颜色只取 <code>--xh-*</code> 或由它调出的 <code>color-mix()</code>，不读应用配色变量，组件局部变量的取值也一样；圆角、内距、间隙只取 <code>--xh-shape-*</code> / <code>--xh-space-*</code>；过渡逐个列属性、不写 <code>all</code>；字号取 <code>--xh-font-size-*</code> / <code>--xh-text-*-size</code>、图标尺寸取 <code>--xh-glyph-size-*</code>，不写 px、rem；原生滚动条只在 <code>scrollbar.css</code> 里给</td></tr><tr><td>裸 px</td><td><code>pnpm px:check</code>：<code>.css</code> 与 <code>.vue</code> 的 <code>&lt;style&gt;</code> 里的裸 px 按文件计数（<code>scripts/px-allowlist.json</code>），只许减不许增，新文件不进白名单；<code>0px</code>、<code>1px</code> / <code>2px</code>（描边与发丝线）、<code>9999px</code> 不计</td></tr><tr><td>令牌</td><td>引用的 <code>--xh-*</code> 必须存在于已安装的组件库里（<code>pnpm token:check</code>）</td></tr><tr><td>修补</td><td>不用页面 CSS 修补组件库的通用缺陷，回 XiHan.UI 修；令牌桥只映射品牌与布局语义，不改组件结构</td></tr><tr><td>风格</td><td>紧凑、任务导向，不在控制台页面用营销式大标题、装饰性 Hero、夸张渐变或装饰留白</td></tr></tbody></table><h2 id="布局" tabindex="-1">布局 <a class="header-anchor" href="#布局" aria-label="Permalink to “布局”">​</a></h2><p><code>packages/layouts/basic</code> 提供前端壳：侧栏、顶栏、标签栏、面包屑、内容区、页脚。偏好中心可切换布局形态（<code>side</code>、<code>side-mixed</code>、<code>top</code>、<code>mix</code>、<code>header-mix</code>、<code>header-sidebar</code>、<code>full</code>）、侧栏宽度、标签样式、内容宽度、页脚等。</p><p>模块经 <code>registerShellExtension</code>（<code>~/stores</code>）向壳层注入顶栏按钮、布局级浮层与布局集成钩子（如聊天的顶栏按钮、浮动面板与实时连接），经 <code>registerWorkbenchWidget</code> 向工作台登记列表型小组件；布局不依赖具体模块，删掉模块目录即随之消失。</p><p>壳层的常驻能力：</p><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>全局搜索</td><td>命令面板，<code>Ctrl / ⌘ + K</code>，支持拼音首字母直达页面</td></tr><tr><td>标签总览</td><td><code>Alt + B</code></td></tr><tr><td>收藏</td><td>页面收藏，跨端同步</td></tr><tr><td>分屏</td><td>两个页面左右并排，窄屏不可用</td></tr><tr><td>通知中心</td><td>顶栏，读收件箱，收到 <code>ReceiveNotification</code> 时刷新</td></tr><tr><td>公告拦截</td><td>强制阅读的公告以不可关闭的弹窗逐条拦截，登录弹窗公告随后逐条弹出</td></tr><tr><td>灵动岛</td><td>实时连接状态、后台任务进度（<code>TaskProgress</code>）、导出与设置同步等过程提示</td></tr><tr><td>锁屏</td><td><code>Alt + L</code>，调 <code>auth.lock</code> / <code>auth.unlock</code>，服务端强制</td></tr><tr><td>切换租户、切换角色、模仿</td><td>顶栏入口（切换租户在控制中心 <code>/control-center</code>）；换会话后整页重建</td></tr><tr><td>水印</td><td>偏好中心开关</td></tr><tr><td>新版本提示</td><td>正式部署的站点定时比对 <code>version.json</code>，有新版本时提示刷新</td></tr></tbody></table><p>快捷键还有 <code>Alt + Q</code> 退出登录，偏好中心里可逐项关闭。</p><h2 id="偏好与同步" tabindex="-1">偏好与同步 <a class="header-anchor" href="#偏好与同步" aria-label="Permalink to “偏好与同步”">​</a></h2><p>亮 / 暗 / 跟随系统、主题色、圆角、密度、字号、色弱 / 灰度、布局、区域与时区等偏好存在本地，并经用户设置（<code>user-settings</code>）跨端同步：开着同步时以后端那份为准，登录或刷新时拉取。偏好与收藏在其他设备上改了经 <code>UserSettingChanged</code> 实时应用；搜索设置、表格设置与看板布局在打开页面时取后端那份。偏好、收藏、搜索、表格与看板各有同步开关（设备本地，不上行），缺省都开。</p><h2 id="无障碍与适配" tabindex="-1">无障碍与适配 <a class="header-anchor" href="#无障碍与适配" aria-label="Permalink to “无障碍与适配”">​</a></h2><ul><li>只有图标的操作要有可访问名称或提示，键盘焦点可见；</li><li>视觉或交互改动在真实浏览器里检查：亮 / 暗色、窄视口（手机宽度）、键盘导航与焦点、减少动态效果；按影响范围再看 RTL、粗指针、强制色与打印。jsdom 不能代替真实布局与计算样式。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./components">常用组件</a> · <a href="./icon">字体图标</a> · <a href="./i18n">国际化与时区</a></li></ul>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};